int unimac_mdio_probe(struct platform_device *pdev)
{
    struct resource *res;
    void __iomem *base;
    struct mii_bus *bus;
    struct unimac_mdio_priv *priv;
    struct device *dev = &pdev->dev;
    int ret;

    priv = devm_kzalloc(dev, sizeof(*priv), GFP_KERNEL);
    if (!priv)
        return -ENOMEM;

    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res)
        return -ENODEV;

    base = devm_ioremap_resource(dev, res);
    if (IS_ERR(base))
        return PTR_ERR(base);

    priv->base = base;

    bus = devm_mdiobus_alloc(dev);
    if (!bus)
        return -ENOMEM;

    bus->name = "UniMAC MDIO Bus";
    bus->read = unimac_mdio_read;
    bus->write = unimac_mdio_write;
    bus->parent = dev;
    snprintf(bus->id, MII_BUS_ID_SIZE, "%s", dev_name(dev));

    bus->phy_mask = ~0;
    bus->irq = kmalloc_array(PHYS_ADDR_MAX, sizeof(int), GFP_KERNEL);
    if (!bus->irq)
        return -ENOMEM;

    if (pdev->dev.platform_data) {
        struct unimac_mdio_pdata *pdata = pdev->dev.platform_data;
        if (pdata->init)
            pdata->init(pdev);
    }

    ret = of_mdiobus_register(bus, dev_of_node(dev));
    if (ret) {
        dev_err(dev, "Failed to register MDIO bus\n");
        kfree(bus->irq);
        return ret;
    }

    platform_set_drvdata(pdev, priv);
    dev_info(dev, "MDIO bus initialized at %pR\n", res);

    return 0;
}

